export interface BlogSummary {
  id: string;
  slug: string;
  title: string;
  sourceUrl: string;
  publishedAt: string;
  excerpt: string;
  image?: string;
  author?: string;
}
export interface BlogPost extends BlogSummary {
  html: string;
}
export const BLOG_TITLE = 'Bible study articles | Revelationary';
export const BLOG_DESCRIPTION =
  'Explore articles about scripture and bring your questions to the Revelationary Bible study community.';
export const articlePath = (slug: string) => `/blog/${slug}/`;
export const articleDate = (date: string) =>
  new Date(date).toLocaleDateString('en-GB', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    timeZone: 'UTC',
  });
export function articleSchema(post: BlogPost) {
  const url = `https://revelationary.online${articlePath(post.slug)}`;
  return {
    '@context': 'https://schema.org',
    '@type': 'BlogPosting',
    '@id': `${url}#article`,
    url,
    mainEntityOfPage: url,
    headline: post.title,
    description: post.excerpt,
    datePublished: post.publishedAt,
    ...(post.image ? { image: post.image } : {}),
    ...(post.author ? { author: { '@type': 'Person', name: post.author } } : {}),
    publisher: {
      '@type': 'Organization',
      name: 'Revelationary',
      url: 'https://revelationary.online/',
    },
  };
}
