import React, { Suspense, useEffect, useState } from 'react';
import PublicLayout, { PublicThemeProps } from '../public-site/PublicLayout';
import GamesEntry from '../public-site/GamesEntry';
import { GAME_PAGES, gamePath } from '../public-site/routes';
import type { GameKind } from '../games/types';
import '../games/games.css';

export const GAMES_TITLE = 'Bible games | Revelationary';
export const GAMES_DESCRIPTION =
  'Play daily Bible Wordle, complete Bible verses and practise scripture with multiple-choice flashcards in your chosen translation.';
export default function GamesPage({
  game,
  leaderboardView = false,
  ...props
}: PublicThemeProps & {
  game?: GameKind;
  leaderboardView?: boolean;
}) {
  const [ready, setReady] = useState(false);
  useEffect(() => {
    setReady(true);
    if (game && window.location.pathname.replace(/\/$/, '') === '/games') {
      window.history.replaceState(null, '', gamePath(game, leaderboardView));
    }
  }, [game, leaderboardView]);
  const page = game ? GAME_PAGES[game] : null;
  const loading = <p role="status">Loading game…</p>;
  return (
    <PublicLayout {...props}>
      <section className="games-page home-width">
        <header className="games-heading">
          <h1>{page?.title || '/games'}</h1>
          <p>{page?.description || 'Read. Remember. Return.'}</p>
        </header>
        {game ? (
          <>
            {!ready && (
              <p>
                <a href="/games/">← All games</a>
              </p>
            )}
            {ready ? (
              <Suspense fallback={loading}>
                <GamesEntry initialGame={game} leaderboardView={leaderboardView} />
              </Suspense>
            ) : (
              loading
            )}
          </>
        ) : (
          <>
            <p className="games-intro">
              A little practice, every day. Explore scripture through three free Bible games.
            </p>
            <div className="games-selection">
              <article>
                <span className="game-number">01 / DAILY</span>
                <img
                  className="game-cover"
                  src="/games/wordle-illustration.webp"
                  alt="Green and brown word-game tiles beside an open Bible."
                  width="768"
                  height="512"
                  loading="lazy"
                  decoding="async"
                />
                <h2>Bible Wordle</h2>
                <p>
                  One five-letter Bible word in English. Six guesses. A new shared puzzle every day.
                </p>
                <a className="game-card-link" href={gamePath('wordle')}>
                  Play today →
                </a>
              </article>
              <article>
                <span className="game-number">02 / PRACTICE</span>
                <img
                  className="game-cover"
                  src="/games/blank-illustration.webp"
                  alt="A blue and yellow verse exercise beside an open Bible."
                  width="768"
                  height="512"
                  loading="lazy"
                  decoding="async"
                />
                <h2>Fill in the blank</h2>
                <p>
                  Complete a verse from your chosen translation. Pick the missing word from three
                  answers.
                </p>
                <a className="game-card-link" href={gamePath('blank')}>
                  Complete a verse →
                </a>
              </article>
              <article>
                <span className="game-number">03 / REMEMBER</span>
                <img
                  className="game-cover"
                  src="/games/flashcards-illustration.webp"
                  alt="Purple scripture memory cards on a warm brown study desk."
                  width="768"
                  height="512"
                  loading="lazy"
                  decoding="async"
                />
                <h2>Verse flashcards</h2>
                <p>
                  Match scripture with its reference in ten-card rounds, with three difficulty
                  levels and a review of missed cards.
                </p>
                <a className="game-card-link" href={gamePath('flashcards')}>
                  Practise verses →
                </a>
              </article>
            </div>
            <p className="games-note">
              Play as a guest. Sign in to save completed Wordle scores, earn trophies and join the
              optional daily leaderboard. Practice games do not change your reading streak.
            </p>
          </>
        )}
        <p className="games-study">
          <a href="/study/">Open the Bible study tool →</a>
        </p>
      </section>
    </PublicLayout>
  );
}
